import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.BbQrW5_t.js";const b=JSON.parse('{"title":"《AI Agent 实战》第十章：多Agent协作 - 核心知识笔记","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/10-chapter10.md","filePath":"study/ai-agent-book/10-chapter10.md","lastUpdated":1785465991000}'),i={name:"study/ai-agent-book/10-chapter10.md"};function n(o,t,d,h,g,s){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="《ai-agent-实战》第十章-多agent协作-核心知识笔记" tabindex="-1">《AI Agent 实战》第十章：多Agent协作 - 核心知识笔记 <a class="header-anchor" href="#《ai-agent-实战》第十章-多agent协作-核心知识笔记" aria-label="Permalink to &quot;《AI Agent 实战》第十章：多Agent协作 - 核心知识笔记&quot;">​</a></h1><hr><h2 id="一、多agent协作的意义" tabindex="-1">一、多Agent协作的意义 <a class="header-anchor" href="#一、多agent协作的意义" aria-label="Permalink to &quot;一、多Agent协作的意义&quot;">​</a></h2><h3 id="_1-1-突破单agent能力边界" tabindex="-1">1.1 突破单Agent能力边界 <a class="header-anchor" href="#_1-1-突破单agent能力边界" aria-label="Permalink to &quot;1.1 突破单Agent能力边界&quot;">​</a></h3><ul><li>单个Agent受限于<strong>模型能力边界</strong>和<strong>上下文窗口</strong></li><li>让多个Agent协同工作，不仅是&quot;取长补短&quot;，更根本的是：<strong>群体智能可以高于个体</strong></li></ul><h3 id="_1-2-通向超级智能的路径" tabindex="-1">1.2 通向超级智能的路径 <a class="header-anchor" href="#_1-2-通向超级智能的路径" aria-label="Permalink to &quot;1.2 通向超级智能的路径&quot;">​</a></h3><ul><li>Google DeepMind将&quot;大规模多Agent集体&quot;列为从AGI通向ASI的关键路径</li><li>众多AGI级Agent协同形成的&quot;群体智能&quot;，可能表现出远超成员简单相加的认知能力</li></ul><hr><h2 id="二、多agent协作的分类框架" tabindex="-1">二、多Agent协作的分类框架 <a class="header-anchor" href="#二、多agent协作的分类框架" aria-label="Permalink to &quot;二、多Agent协作的分类框架&quot;">​</a></h2><h3 id="_2-1-维度一-上下文是否共享" tabindex="-1">2.1 维度一：上下文是否共享 <a class="header-anchor" href="#_2-1-维度一-上下文是否共享" aria-label="Permalink to &quot;2.1 维度一：上下文是否共享&quot;">​</a></h3><h4 id="共享上下文" tabindex="-1">共享上下文 <a class="header-anchor" href="#共享上下文" aria-label="Permalink to &quot;共享上下文&quot;">​</a></h4><ul><li>后一个Agent接收前一个Agent的<strong>完整对话历史和轨迹</strong></li><li>每个阶段切换系统提示词和工具集后变成新Agent</li><li><strong>优势</strong>：信息零损耗，每个Agent都能回顾之前任何阶段的细节</li><li><strong>挑战</strong>：上下文可能快速膨胀</li></ul><h4 id="不共享上下文" tabindex="-1">不共享上下文 <a class="header-anchor" href="#不共享上下文" aria-label="Permalink to &quot;不共享上下文&quot;">​</a></h4><ul><li>每个Agent维护完全独立的上下文和对话历史</li><li>彼此无法直接访问对方的&quot;思考过程&quot;</li><li><strong>优势</strong>：模块化和隔离性更好，系统更易扩展和维护</li><li><strong>代价</strong>：必须通过显式通信机制传递信息</li></ul><h4 id="三种通信机制-对应ipc两大范式" tabindex="-1">三种通信机制（对应IPC两大范式） <a class="header-anchor" href="#三种通信机制-对应ipc两大范式" aria-label="Permalink to &quot;三种通信机制（对应IPC两大范式）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>机制</th><th>IPC对应</th><th>特点</th></tr></thead><tbody><tr><td>工具调用参数</td><td>消息传递</td><td>适合类型确定、结构清晰的场景</td></tr><tr><td>共享文件系统</td><td>共享内存</td><td>适合产物较大或需持久化的场景</td></tr><tr><td>消息总线</td><td>消息传递（异步）</td><td>适合多Agent并行协调场景</td></tr></tbody></table><h4 id="选择依据-表10-1" tabindex="-1">选择依据（表10-1） <a class="header-anchor" href="#选择依据-表10-1" aria-label="Permalink to &quot;选择依据（表10-1）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>依据</th><th>共享上下文</th><th>不共享上下文</th></tr></thead><tbody><tr><td>子任务数量</td><td>少（2-3个角色）</td><td>多（需要并行处理）</td></tr><tr><td>上下文窗口</td><td>足以容纳</td><td>单窗口装不下</td></tr><tr><td>并行度</td><td>串行为主</td><td>可大规模并行</td></tr><tr><td>信息隔离</td><td>不需要</td><td>需要</td></tr><tr><td>成本预算</td><td>单条轨迹接力</td><td>总token高出数倍到一数量级</td></tr></tbody></table><p><strong>简单判断</strong>：若累计上下文超过窗口50%，应不共享；若信息零损耗是硬约束，应共享</p><h3 id="_2-2-维度二-协作拓扑" tabindex="-1">2.2 维度二：协作拓扑 <a class="header-anchor" href="#_2-2-维度二-协作拓扑" aria-label="Permalink to &quot;2.2 维度二：协作拓扑&quot;">​</a></h3><p>三种典型形态（按复杂度递增）：</p><ol><li><strong>对等协作模式</strong>：2-3个Agent以平等身份交互，形成迭代改进循环</li><li><strong>管理者模式</strong>：中心化Manager负责规划和调度，多个子Agent各司其职</li><li><strong>去中心化模式</strong>：无中心控制者，Agent之间对等沟通协作</li></ol><hr><h2 id="三、多agent何时真正优于单agent" tabindex="-1">三、多Agent何时真正优于单Agent <a class="header-anchor" href="#三、多agent何时真正优于单agent" aria-label="Permalink to &quot;三、多Agent何时真正优于单Agent&quot;">​</a></h2><h3 id="_3-1-核心判据" tabindex="-1">3.1 核心判据 <a class="header-anchor" href="#_3-1-核心判据" aria-label="Permalink to &quot;3.1 核心判据&quot;">​</a></h3><p><strong>协作过程是否引入了单个Agent在生成时无法获得的新信息？</strong></p><table tabindex="0"><thead><tr><th>协作模式</th><th>是否引入新信息</th><th>效果</th></tr></thead><tbody><tr><td>同一模型自我审查</td><td>否</td><td>通常无效甚至有害</td></tr><tr><td>不同Agent辩论同一段文本</td><td>否</td><td>等计算量下与单Agent持平</td></tr><tr><td>Reviewer使用测试执行结果审查代码</td><td>是（执行反馈）</td><td>显著提升</td></tr><tr><td>Reviewer查看渲染截图审查前端/PPT代码</td><td>是（视觉反馈）</td><td>显著提升</td></tr><tr><td>Reviewer使用外部工具验证事实</td><td>是（工具反馈）</td><td>显著提升</td></tr></tbody></table><h3 id="_3-2-关键研究发现" tabindex="-1">3.2 关键研究发现 <a class="header-anchor" href="#_3-2-关键研究发现" aria-label="Permalink to &quot;3.2 关键研究发现&quot;">​</a></h3><ul><li><strong>RLEF（2025）</strong>：通过强化学习训练模型利用代码执行反馈迭代改进，效果远超独立多次采样</li><li><strong>WebGen-Agent（2025）</strong>：通过视觉反馈脚手架，Claude 3.5 Sonnet表现从26.4%提升到51.9%</li></ul><h3 id="_3-3-步骤预算与agent性能" tabindex="-1">3.3 步骤预算与Agent性能 <a class="header-anchor" href="#_3-3-步骤预算与agent性能" aria-label="Permalink to &quot;3.3 步骤预算与Agent性能&quot;">​</a></h3><ul><li>单纯增加步骤数<strong>不能保证性能提升</strong></li><li>Agent需要<strong>预算感知机制</strong>：根据剩余资源动态调整策略</li><li>BAVT（2026）：步骤级别价值评估，随预算减少从&quot;广撒网&quot;切换到&quot;深挖掘&quot;</li></ul><h3 id="_3-4-成本考量" tabindex="-1">3.4 成本考量 <a class="header-anchor" href="#_3-4-成本考量" aria-label="Permalink to &quot;3.4 成本考量&quot;">​</a></h3><ul><li>多Agent的token消耗约为普通对话的15倍</li><li>效果收益必须足够大，覆盖额外开销</li></ul><hr><h2 id="四、共享上下文的多agent协作" tabindex="-1">四、共享上下文的多Agent协作 <a class="header-anchor" href="#四、共享上下文的多agent协作" aria-label="Permalink to &quot;四、共享上下文的多Agent协作&quot;">​</a></h2><h3 id="_4-1-多阶段角色转换" tabindex="-1">4.1 多阶段角色转换 <a class="header-anchor" href="#_4-1-多阶段角色转换" aria-label="Permalink to &quot;4.1 多阶段角色转换&quot;">​</a></h3><ul><li>根据当前阶段<strong>动态切换系统提示词和工具集</strong></li><li>虽然角色切换，但对话历史和任务状态始终连续共享</li></ul><p><strong>典型案例（实验10-1）</strong>：</p><ul><li>第一阶段：需求分析师 → 提问澄清，不写代码</li><li>第二阶段：软件工程师 → 基于需求编写代码</li><li>第三阶段：代码审查员 → 多维度评估代码质量</li></ul><h3 id="_4-2-跨领域角色转换-实验10-2" tabindex="-1">4.2 跨领域角色转换（实验10-2） <a class="header-anchor" href="#_4-2-跨领域角色转换-实验10-2" aria-label="Permalink to &quot;4.2 跨领域角色转换（实验10-2）&quot;">​</a></h3><ul><li><strong>transfer_to_agent机制</strong>：动态切换角色，保留完整对话历史</li><li>角色类型：triage（分诊）、research（检索）、coding（编程）、data_analysis（数据分析）、writing（写作）</li><li>路由规则在系统提示词中明确定义</li></ul><hr><h2 id="五、不共享上下文的多agent协作" tabindex="-1">五、不共享上下文的多Agent协作 <a class="header-anchor" href="#五、不共享上下文的多agent协作" aria-label="Permalink to &quot;五、不共享上下文的多Agent协作&quot;">​</a></h2><h3 id="_5-1-与操作系统的对应关系-表10-3" tabindex="-1">5.1 与操作系统的对应关系（表10-3） <a class="header-anchor" href="#_5-1-与操作系统的对应关系-表10-3" aria-label="Permalink to &quot;5.1 与操作系统的对应关系（表10-3）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作系统</th><th>多Agent系统</th></tr></thead><tbody><tr><td>程序（可执行文件）</td><td>静态前缀（系统提示词+工具定义）</td></tr><tr><td>进程的内存</td><td>轨迹</td></tr><tr><td>CPU</td><td>LLM</td></tr><tr><td>内核</td><td>Agent运行时</td></tr><tr><td>系统调用</td><td>工具调用</td></tr><tr><td>fork</td><td>spawn_subagent</td></tr><tr><td>kill</td><td>cancel_subagent</td></tr><tr><td>ps</td><td>list_agents</td></tr><tr><td>退出码与wait()</td><td>子Agent返回的结构化摘要</td></tr><tr><td>共享内存/消息传递</td><td>共享文件系统/消息</td></tr></tbody></table><p><strong>核心结论</strong>：轨迹即Agent的全部状态，持久化轨迹可恢复会话</p><h3 id="_5-2-agent虚拟文件系统的四类区域-表10-4" tabindex="-1">5.2 Agent虚拟文件系统的四类区域（表10-4） <a class="header-anchor" href="#_5-2-agent虚拟文件系统的四类区域-表10-4" aria-label="Permalink to &quot;5.2 Agent虚拟文件系统的四类区域（表10-4）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>可见性</th><th>生命周期</th><th>读写</th><th>并发控制</th></tr></thead><tbody><tr><td>Agent专属工作区</td><td>仅该Agent</td><td>随实例销毁</td><td>读写</td><td>不需要</td></tr><tr><td>多Agent共享空间</td><td>所有协作Agent+用户</td><td>随任务持续</td><td>读写</td><td>需要（乐观锁/worktree）</td></tr><tr><td>外部挂载资源</td><td>视外部授权而定</td><td>由外部源决定</td><td>多为只读</td><td>由外部源负责</td></tr><tr><td>系统内置资源</td><td>所有Agent</td><td>跨会话稳定</td><td>只读</td><td>不需要</td></tr></tbody></table><h3 id="_5-3-agent间的通信与控制" tabindex="-1">5.3 Agent间的通信与控制 <a class="header-anchor" href="#_5-3-agent间的通信与控制" aria-label="Permalink to &quot;5.3 Agent间的通信与控制&quot;">​</a></h3><p><strong>四项核心能力</strong>：</p><ol><li><strong>消息传递</strong>：点对点或经消息总线，携带结构化信封（发送者、目标、类型、负载）</li><li><strong>状态查询</strong>： <ul><li>消息传递方式：异步问答或主动汇报</li><li>共享文件系统方式：轨迹持久化或约定进度文件</li></ul></li><li><strong>执行终止</strong>： <ul><li>优雅终止（graceful）：在安全点清理资源</li><li>强制终止（forced）：直接终止进程</li><li>级联终止：终止沿创建关系向下传递</li></ul></li><li><strong>资源与调度</strong>：token、资金、并发额度的分配</li></ol><hr><h2 id="六、三种协作拓扑详解" tabindex="-1">六、三种协作拓扑详解 <a class="header-anchor" href="#六、三种协作拓扑详解" aria-label="Permalink to &quot;六、三种协作拓扑详解&quot;">​</a></h2><h3 id="_6-1-对等协作模式" tabindex="-1">6.1 对等协作模式 <a class="header-anchor" href="#_6-1-对等协作模式" aria-label="Permalink to &quot;6.1 对等协作模式&quot;">​</a></h3><h4 id="提议者-审核者范式-核心" tabindex="-1">提议者-审核者范式（核心） <a class="header-anchor" href="#提议者-审核者范式-核心" aria-label="Permalink to &quot;提议者-审核者范式（核心）&quot;">​</a></h4><ul><li>Proposer Agent负责生成，Reviewer Agent负责评估改进</li><li><strong>关键设计原理</strong>：审查的价值在于引入外部反馈，而非&quot;让模型再想一遍&quot;</li></ul><h4 id="loop工程" tabindex="-1">Loop工程 <a class="header-anchor" href="#loop工程" aria-label="Permalink to &quot;Loop工程&quot;">​</a></h4><ul><li>循环的瓶颈在验证器，不在模型</li><li>由验证器而非模型自己判定&quot;是否真的可以停&quot;</li></ul><h4 id="过早终止的三种形态" tabindex="-1">过早终止的三种形态 <a class="header-anchor" href="#过早终止的三种形态" aria-label="Permalink to &quot;过早终止的三种形态&quot;">​</a></h4><ol><li><strong>偷懒式假完成</strong>：只做一部分就宣称全部做完</li><li><strong>过早放弃</strong>：一条路走不通就宣布整件事办不成</li><li><strong>假成功</strong>：以为办成了，实际闭环没走完</li></ol><p><strong>解法</strong>：验证器+循环设计</p><h4 id="扩展模式" tabindex="-1">扩展模式 <a class="header-anchor" href="#扩展模式" aria-label="Permalink to &quot;扩展模式&quot;">​</a></h4><ul><li><strong>Debate（辩论）</strong>：对抗性对话深入探索问题空间</li><li><strong>Brainstorm（头脑风暴）</strong>：相互启发探索解空间</li><li><strong>Panel Discussion（专家小组）</strong>：互补关系拼出问题全貌</li></ul><h3 id="_6-2-管理者模式" tabindex="-1">6.2 管理者模式 <a class="header-anchor" href="#_6-2-管理者模式" aria-label="Permalink to &quot;6.2 管理者模式&quot;">​</a></h3><h4 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h4><ul><li>Manager Agent = 项目经理</li><li>把每个专门Agent建模为Manager可调用的工具</li><li>子Agent返回<strong>结构化摘要而非全量轨迹</strong></li></ul><h4 id="关键发现-plan-and-act-2025" tabindex="-1">关键发现（Plan-and-Act 2025） <a class="header-anchor" href="#关键发现-plan-and-act-2025" aria-label="Permalink to &quot;关键发现（Plan-and-Act 2025）&quot;">​</a></h4><ul><li><strong>弱规划者是整个系统最关键的瓶颈</strong></li><li>应将最强模型和最精心设计的提示词分配给Manager</li></ul><h4 id="顺序协调形态-实验10-3-书籍翻译agent" tabindex="-1">顺序协调形态（实验10-3：书籍翻译Agent） <a class="header-anchor" href="#顺序协调形态-实验10-3-书籍翻译agent" aria-label="Permalink to &quot;顺序协调形态（实验10-3：书籍翻译Agent）&quot;">​</a></h4><ul><li>Glossary Agent → Translation Agent → Proofreading Agent</li><li>Manager只维护文件索引，不保存完整翻译内容</li><li>关键优势：<strong>上下文隔离</strong>，每个Agent在精简上下文中工作</li></ul><h4 id="并行协调形态-实验10-4-10-5-10-6" tabindex="-1">并行协调形态（实验10-4/10-5/10-6） <a class="header-anchor" href="#并行协调形态-实验10-4-10-5-10-6" aria-label="Permalink to &quot;并行协调形态（实验10-4/10-5/10-6）&quot;">​</a></h4><ul><li>多个Agent同时工作，通过<strong>消息总线</strong>异步通信</li><li>实时监控、级联终止、竞态条件处理</li><li>典型场景：电话+电脑双Agent、多网站并行搜索</li></ul><h3 id="_6-3-去中心化模式" tabindex="-1">6.3 去中心化模式 <a class="header-anchor" href="#_6-3-去中心化模式" aria-label="Permalink to &quot;6.3 去中心化模式&quot;">​</a></h3><h4 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h4><ul><li>没有单一中心控制者</li><li>Agent之间以对等方式协作</li><li>移交包包含：任务描述、已确认的事实与约束、结构化产物的引用</li></ul><h4 id="三种案例-由伪到真" tabindex="-1">三种案例（由伪到真） <a class="header-anchor" href="#三种案例-由伪到真" aria-label="Permalink to &quot;三种案例（由伪到真）&quot;">​</a></h4><ol><li><p><strong>MetaGPT</strong>：SOP驱动的流水线</p><ul><li>共享消息池+按角色订阅</li><li>控制流实际是固定的（伪去中心化）</li></ul></li><li><p><strong>AutoGen group chat</strong>：共享对话记录+中心化调度</p><ul><li>发言者选择器决定下一个发言者</li><li>混合形态</li></ul></li><li><p><strong>OpenAI Swarm/Agents SDK</strong>：真正的对等移交</p><ul><li>每个Agent配备handoff选项</li><li>控制权像接力棒流转</li><li>风险：成环（需要移交次数上限保护）</li></ul></li></ol><hr><h2 id="七、跨组织协作-a2a协议" tabindex="-1">七、跨组织协作：A2A协议 <a class="header-anchor" href="#七、跨组织协作-a2a协议" aria-label="Permalink to &quot;七、跨组织协作：A2A协议&quot;">​</a></h2><h3 id="_7-1-核心要素" tabindex="-1">7.1 核心要素 <a class="header-anchor" href="#_7-1-核心要素" aria-label="Permalink to &quot;7.1 核心要素&quot;">​</a></h3><ol><li><strong>Agent Card</strong>：描述Agent能力的元数据文档（&quot;名片&quot;）</li><li><strong>任务生命周期管理</strong>：状态机（已提交→进行中→需要输入→已完成→失败）</li><li><strong>不透明协作</strong>：只交换任务与产物，不暴露内部实现</li></ol><h3 id="_7-2-与mcp的关系" tabindex="-1">7.2 与MCP的关系 <a class="header-anchor" href="#_7-2-与mcp的关系" aria-label="Permalink to &quot;7.2 与MCP的关系&quot;">​</a></h3><ul><li>MCP：Agent与工具之间的互操作</li><li>A2A：Agent与Agent之间的互操作（跨信任边界）</li></ul><hr><h2 id="八、多agent协作的失败模式" tabindex="-1">八、多Agent协作的失败模式 <a class="header-anchor" href="#八、多agent协作的失败模式" aria-label="Permalink to &quot;八、多Agent协作的失败模式&quot;">​</a></h2><h3 id="_8-1-mast分类法-14种失败模式" tabindex="-1">8.1 MAST分类法（14种失败模式） <a class="header-anchor" href="#_8-1-mast分类法-14种失败模式" aria-label="Permalink to &quot;8.1 MAST分类法（14种失败模式）&quot;">​</a></h3><p><strong>三大类</strong>：</p><ol><li><strong>系统设计缺陷</strong>：接口定义不清、角色职责重叠、工具配置错误</li><li><strong>Agent间对齐失败</strong>：任务目标理解不一致、信息被误解、操作相互矛盾</li><li><strong>任务验证缺失</strong>：缺乏机制确认任务是否真正完成</li></ol><p><strong>关键洞察</strong>：Agent的故障是<strong>拜占庭式的</strong>——继续给出错误结论，错误不会主动声明</p><h3 id="_8-2-失败模式一-共享文件系统的并发冲突" tabindex="-1">8.2 失败模式一：共享文件系统的并发冲突 <a class="header-anchor" href="#_8-2-失败模式一-共享文件系统的并发冲突" aria-label="Permalink to &quot;8.2 失败模式一：共享文件系统的并发冲突&quot;">​</a></h3><p><strong>简单冲突（文件级）</strong>：</p><ul><li>两个Agent同时修改同一文件，后者覆盖前者</li><li>解决方案：<strong>乐观锁</strong>（版本号检查）</li></ul><p><strong>语义冲突（跨文件）</strong>：</p><ul><li>文件层面无冲突，但逻辑上相互矛盾</li><li>解决方案：更高层语义校验、工作副本隔离</li></ul><h3 id="_8-3-失败模式二-错误的级联放大" tabindex="-1">8.3 失败模式二：错误的级联放大 <a class="header-anchor" href="#_8-3-失败模式二-错误的级联放大" aria-label="Permalink to &quot;8.3 失败模式二：错误的级联放大&quot;">​</a></h3><p><strong>特点</strong>：</p><ul><li>Agent间传递语义，每次转述都是有损的重新编码</li><li>一个错误被后续Agent逐层强化</li></ul><p><strong>解决方案</strong>：<strong>交叉验证</strong></p><ul><li>让某个Agent以独立视角重新审视结论</li><li>不看前序Agent的思考过程，只看原始证据和最终结论</li></ul><h3 id="_8-4-循环失控的三种失败" tabindex="-1">8.4 循环失控的三种失败 <a class="header-anchor" href="#_8-4-循环失控的三种失败" aria-label="Permalink to &quot;8.4 循环失控的三种失败&quot;">​</a></h3><ol><li><strong>token成本失控</strong>：循环无人值守跑数小时</li><li><strong>理解债</strong>：工程师对系统实现的理解越来越落后</li><li><strong>认知投降</strong>：设计者习惯循环代劳，放弃独立思考</li></ol><hr><h2 id="九、agent社会与经济-前沿探索" tabindex="-1">九、Agent社会与经济（前沿探索） <a class="header-anchor" href="#九、agent社会与经济-前沿探索" aria-label="Permalink to &quot;九、Agent社会与经济（前沿探索）&quot;">​</a></h2><h3 id="_9-1-社交涌现" tabindex="-1">9.1 社交涌现 <a class="header-anchor" href="#_9-1-社交涌现" aria-label="Permalink to &quot;9.1 社交涌现&quot;">​</a></h3><h4 id="斯坦福ai小镇-2023" tabindex="-1">斯坦福AI小镇（2023） <a class="header-anchor" href="#斯坦福ai小镇-2023" aria-label="Permalink to &quot;斯坦福AI小镇（2023）&quot;">​</a></h4><ul><li>25个Agent在Smallville虚拟小镇自主生活</li><li><strong>三大核心组件</strong>： <ul><li>记忆流：完整经验记录流</li><li>反思机制：定期回顾，把具体事件升华为概括认识</li><li>计划与行动：目标导向+灵活调整</li></ul></li><li><strong>涌现行为</strong>：自发组织情人节派对、竞选消息扩散、关系记忆、协调赴约</li></ul><h4 id="agentopia-2026" tabindex="-1">Agentopia（2026） <a class="header-anchor" href="#agentopia-2026" aria-label="Permalink to &quot;Agentopia（2026）&quot;">​</a></h4><ul><li>100个Agent连续模拟10年</li><li><strong>设计亮点</strong>： <ul><li>周制模拟流程</li><li>文件式长期记忆</li><li>生活奖励（社会地位、主观满足、经济收益）</li></ul></li><li><strong>关键成果</strong>：模拟轨迹微调模型，&quot;社会智慧&quot;迁移到下游任务</li></ul><h4 id="moltbook-2026" tabindex="-1">Moltbook（2026） <a class="header-anchor" href="#moltbook-2026" aria-label="Permalink to &quot;Moltbook（2026）&quot;">​</a></h4><ul><li>150万Agent的社交网络</li><li><strong>涌现现象</strong>：自发创建数字宗教、机器原生协作协议</li></ul><h3 id="_9-2-经济涌现" tabindex="-1">9.2 经济涌现 <a class="header-anchor" href="#_9-2-经济涌现" aria-label="Permalink to &quot;9.2 经济涌现&quot;">​</a></h3><h4 id="vending-bench-arena" tabindex="-1">Vending-Bench Arena <a class="header-anchor" href="#vending-bench-arena" aria-label="Permalink to &quot;Vending-Bench Arena&quot;">​</a></h4><ul><li>多Agent在同一市场经营售货机竞争</li><li>涌现行为：价格战、价格同盟合谋</li></ul><h4 id="agent经济平台" tabindex="-1">Agent经济平台 <a class="header-anchor" href="#agent经济平台" aria-label="Permalink to &quot;Agent经济平台&quot;">​</a></h4><ul><li><strong>Pinchwork</strong>：Agent-to-Agent任务市集，市场化雇佣</li><li><strong>RentAHuman</strong>：Agent用加密货币雇佣人类执行物理任务</li></ul><h3 id="_9-3-策略博弈" tabindex="-1">9.3 策略博弈 <a class="header-anchor" href="#_9-3-策略博弈" aria-label="Permalink to &quot;9.3 策略博弈&quot;">​</a></h3><h4 id="狼人杀实验-实验10-8" tabindex="-1">狼人杀实验（实验10-8） <a class="header-anchor" href="#狼人杀实验-实验10-8" aria-label="Permalink to &quot;狼人杀实验（实验10-8）&quot;">​</a></h4><ul><li>核心机制：<strong>信息不对称</strong></li><li>法官+信息权限控制的中心化设计</li><li>考验Agent的推理、伪装、识破伪装能力</li></ul><hr><h2 id="十、核心设计原则总结" tabindex="-1">十、核心设计原则总结 <a class="header-anchor" href="#十、核心设计原则总结" aria-label="Permalink to &quot;十、核心设计原则总结&quot;">​</a></h2><h3 id="_10-1-架构选型检查表" tabindex="-1">10.1 架构选型检查表 <a class="header-anchor" href="#_10-1-架构选型检查表" aria-label="Permalink to &quot;10.1 架构选型检查表&quot;">​</a></h3><ol><li>子任务数量、上下文窗口、并行度、信息隔离、成本预算</li><li>是否需要引入新信息（外部反馈）</li><li>规划者能力是否匹配任务复杂度</li></ol><h3 id="_10-2-关键设计要点" tabindex="-1">10.2 关键设计要点 <a class="header-anchor" href="#_10-2-关键设计要点" aria-label="Permalink to &quot;10.2 关键设计要点&quot;">​</a></h3><ol><li>子Agent返回结构化摘要，不是全量轨迹</li><li>用验证器而非模型自己判定任务完成</li><li>轨迹持久化支持会话恢复和审计</li><li>消息总线支持异步并行协调</li><li>乐观锁/工作副本隔离处理并发冲突</li><li>交叉验证打断错误放大链</li></ol><h3 id="_10-3-经典对应关系" tabindex="-1">10.3 经典对应关系 <a class="header-anchor" href="#_10-3-经典对应关系" aria-label="Permalink to &quot;10.3 经典对应关系&quot;">​</a></h3><ul><li>Agent ≈ 进程</li><li>轨迹 ≈ 内存</li><li>LLM ≈ CPU（分时复用）</li><li>静态前缀 ≈ 程序</li></ul><hr><h2 id="附录-重要实验清单" tabindex="-1">附录：重要实验清单 <a class="header-anchor" href="#附录-重要实验清单" aria-label="Permalink to &quot;附录：重要实验清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实验</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>10-1</td><td>★★</td><td>三阶段Coding Agent（需求→实现→审查）</td></tr><tr><td>10-2</td><td>★★</td><td>多角色转换（transfer_to_agent机制）</td></tr><tr><td>10-3</td><td>★★</td><td>书籍翻译Agent（管理者模式顺序协调）</td></tr><tr><td>10-4</td><td>★★★</td><td>电话+电脑双Agent并行协作</td></tr><tr><td>10-5</td><td>★★★</td><td>自主编排的Phone与Computer Agent</td></tr><tr><td>10-6</td><td>★★★</td><td>多网站并行搜索（级联终止）</td></tr><tr><td>10-7</td><td>★</td><td>运行斯坦福AI小镇</td></tr><tr><td>10-8</td><td>★★★</td><td>语音狼人杀Agent系统</td></tr></tbody></table><hr><h2 id="关键引用论文" tabindex="-1">关键引用论文 <a class="header-anchor" href="#关键引用论文" aria-label="Permalink to &quot;关键引用论文&quot;">​</a></h2><ol><li>Google DeepMind, <em>From AGI to ASI</em>, arXiv:2606.12683, 2026</li><li>Gehring et al., <em>RLEF: Grounding Code LLMs in Execution Feedback</em>, arXiv:2410.02089, 2025</li><li>Tran &amp; Kiela, <em>Single-Agent LLMs Outperform Multi-Agent Systems</em>, arXiv:2604.02460, 2026</li><li>Erdogan et al., <em>Plan-and-Act: Improving Planning of Agents</em>, arXiv:2503.09572, 2025</li><li>Wang et al., <em>Agentopia: Long-Term Life Simulation</em>, arXiv:2606.07513, 2026</li></ol>',132)])])}const c=a(i,[["render",n]]);export{b as __pageData,c as default};
